// Hand-written explanations, keyed by definition ID (see data/manifest/*.json for the IDs).
// A new manifest never changes this file. Definitions without an entry show their docstring.
// The text can use small HTML: <code>, <b>, <i>, and entities such as &lt;.

import type { DefId } from "../src/data/types";

export type Explanation = {
  /** One or two sentences: what the definition does. */
  what: string;
  /** "How it works", as numbered steps. */
  steps: string[];
  /** A note under the steps: why it is built this way, or a real example. */
  aside?: string;
};

export const EXPLANATIONS: Record<DefId, Explanation> = {
  "cmeval.cli.cmd_import": { what: "Runs <code>cmeval import</code>. It picks the output file, starts the importer, and prints what was written and what was skipped.",
    steps: ["Output file: <code>--out</code>, or <code>tasks/swebv-dev&lt;n&gt;.jsonl</code>.", "Run <code>import_swebench_verified(n, seed, revision, out)</code>.", "Print \"N tasks written\", or \"only K of N found; file not changed\".", "Print each skipped row with its reason, then the label stats.", "Exit code 0 only if the file was written."] },
  "cmeval.importers.swebench.import_swebench_verified": { what: "The importer. It takes rows in a balanced order, labels each row, and keeps the first n good tasks. It writes the file only when it has all n.",
    steps: ["No rows given: download the dataset at a pinned revision and load the rows.", "For each row in <code>balanced_order(rows, seed)</code>, until there are n tasks:", "Label it with <code>label_at_commit</code>. A <code>LabelError</code> skips the row and records the reason.", "No gold code file: skip. Else build the task with <code>row_to_task</code>.", "<code>validate(task)</code> finds problems: skip. Else keep the task.", "Sort by repo and ID. If all n were found: <code>save_tasks</code>, then write the <code>.meta.json</code> file."],
    aside: "A failed run never replaces a committed task file. Git or network errors stop the import, so a repo is never missing without notice." },
  "cmeval.importers.swebench.balanced_order": { what: "Gives a fixed row order that takes about the same number of rows from each repo.",
    steps: ["Group the rows by repo.", "For each repo, in sorted order: sort its rows by ID, then shuffle them with the seed <code>\"&lt;seed&gt;:&lt;repo&gt;\"</code>.", "Take one row from each repo in turn (round-robin) until every queue is empty."],
    aside: "The same seed always gives the same order. Small repos run out first; the rest of the rows come from bigger repos." },
  "cmeval.importers.swebench.row_to_task": { what: "Turns one SWE-bench row and its labels into a <code>Task</code> (one line of the answer key).",
    steps: ["Clean the query: remove hidden HTML comments (<code>clean_query</code>).", "Read the PR number from the instance ID.", "Keep only the code part of the patch (<code>split_patch</code>).", "Add tags: label counts, <code>has_test_patch</code>, <code>identifier_in_query</code>.", "Build the <code>Task</code> with split \"dev\" and the labeler version."] },
  "cmeval.repos.ensure_clone": { what: "Clones a repo once, as a bare clone (git data only, no working files).",
    steps: ["The clone does not exist: clone into <code>&lt;name&gt;.partial</code> with <code>core.autocrlf=false</code>, then rename it to the final name.", "Set <code>core.autocrlf=false</code> on the clone, also on clones made before this setting.", "Return the clone path."],
    aside: "A stopped clone never looks like a finished one, because only a complete clone gets the final name. <code>core.autocrlf=false</code> keeps line endings as they are, so file contents, hit texts, and token counts are the same on Windows and on a Mac." },
  "cmeval.repos.ensure_commit": { what: "Makes sure the clone has one exact commit.",
    steps: ["The sha must be a full 40-character sha.", "<code>ensure_clone(repo)</code>.", "The commit is there: done.", "Fetch all branches and tags.", "Still missing: fetch the commit by its sha.", "Still missing: <code>RepoError</code>."] },
  "cmeval.repos.read_file": { what: "Reads one file as it was at a commit, with no checkout. This is the code time machine.",
    steps: ["<code>ensure_commit(repo, commit)</code>.", "Run <code>git show &lt;commit&gt;:&lt;path&gt;</code> and keep the raw bytes.", "The file does not exist at that commit: return None. Any other git error: <code>RepoError</code>.", "Decode the bytes as UTF-8."],
    aside: "Bytes, not text mode. Text mode can change line endings, and that can move line numbers." },
  "cmeval.patches.parse_patch": { what: "Reads a unified diff into one <code>FileChange</code> for each file.",
    steps: ["Parse the diff with unidiff.", "For each file: path, status (added, modified, deleted), file class (code, test, other), and language.", "Record the base-side lines that the change touches."] },
  "cmeval.patches.align_file_diff": { what: "Applies a one-file diff to the base file the way <code>git apply</code> does, and finds the real line numbers.",
    steps: ["For each hunk: <i>want</i> = its context lines and removed lines.", "Try the line that the hunk states. Not an exact match: look 1 line up, 1 down, 2 up, 2 down, and so on, for the nearest exact match.", "No exact match anywhere: <code>PatchMismatch</code>. The diff does not belong to this base.", "Record the offset (found line minus stated line). Copy the base lines and apply the changes.", "Return the fixed text, changed base lines, insertion points, offsets, and added lines."],
    aside: "Example: in scikit-learn-10908 the hunk says line 971, but the matching lines are lower in the file. The search finds them, so the labels point at the real code." },
  "cmeval.labels.label_at_commit": { what: "Labels a patch against a repo at one commit. It joins the labeler to the code time machine.",
    steps: ["Call <code>label_patch(patch, read_base)</code>.", "<code>read_base(path)</code> is <code>repos.read_file(repo, commit, path)</code>."] },
  "cmeval.labels.label_patch": { what: "The labeler. It finds the gold files, classes, and functions that a fix changed.",
    steps: ["<code>parse_patch</code>. Skip files that are not code.", "A new file does not exist at base: its code goes to <i>unretrievable</i>.", "Else read the base file and <code>align_file_diff</code> to get the real changed lines.", "The file is gold. Each changed line range goes to <code>gold.lines</code>.", "<code>find_definitions</code> on the base file. For each changed line, the innermost function and the innermost class around it turn gold.", "Added lines are placed in the fixed file, then mapped back to base definitions.", "Definitions that exist only after the fix go to <i>unretrievable</i>."],
    aside: "A new method added after method A makes the class gold, not A. Only code that existed at the base commit can be gold." },
  "cmeval.labels.find_definitions": { what: "Finds all named functions and classes in a source file, with tree-sitter.",
    steps: ["Parse the source with the language's tree-sitter grammar.", "Walk the tree. Each function or class node in the language table becomes a <code>Definition</code>: kind, qualified name (for example <code>Class.method</code>), start and end line.", "Anonymous functions do not count.", "Also return whether the parse had errors."] },
  "cmeval.tasks.validate": { what: "Checks one task against the schema and returns every problem. An empty list means the task is valid.",
    steps: ["Check each field and its type.", "Check the gold paths and line spans.", "Collect every problem, not only the first one."] },
  "cmeval.tasks.save_tasks": { what: "Validates all tasks, then writes the file in a way that a crash cannot break.",
    steps: ["<code>validate</code> each task and look for duplicate IDs.", "Any problem: raise <code>TaskError</code> with the full list. Nothing is written.", "Write one JSON line for each task to a temp file next to the target.", "Rename the temp file over the target in one step.", "Any error: delete the temp file."] },
  "cmeval.retriever.check_hits": { what: "Checks a system's hits against the contract before anyone grades them.",
    steps: ["Granularity must be \"file\" or \"line\".", "At most k hits.", "Each hit is a <code>Hit</code> with a repo-relative path.", "File systems: no line numbers. Line systems: start and end on every hit, with 1 &le; start &le; end.", "Any break: <code>RetrieverError</code>."],
    aside: "Without this check, a missing line range would turn into a file-level hit without notice (Decision 4)." },
  "cmeval.retriever.Retriever": { what: "The plug. The runner talks only to this interface. grep, grep-fn, codemem, and later systems are adapters that implement it.",
    steps: ["<code>describe()</code>: everything needed to repeat a run.", "<code>index_key()</code>: a hash of index settings. Same key, shared index.", "<code>build()</code> and <code>update()</code>: full index, or catch up after the repo moved.", "<code>search(query, k)</code>: best hits first.", "<code>close()</code>: free models and files."] },
  "cmeval.systems.make_system": { what: "Builds one retrieval system from its config entry.",
    steps: ["Look up the adapter's module and factory in <code>ADAPTERS</code> (fake, grep, grep_fn, codemem).", "Import it. A missing package gives a <code>SystemsError</code> that names the system.", "Call the factory with the settings. Bad settings, or any other error (for example ripgrep is missing), give a <code>SystemsError</code> that names the system.", "The result must implement <code>Retriever</code> and have a valid granularity."] },
  "cmeval.systems.load_systems": { what: "Reads a TOML file of system configs.",
    steps: ["Parse the TOML.", "<code>parse_systems</code> checks each entry: a safe, unique name and a known adapter."] },
  "cmeval.adapters.fake.FakeRetriever": { what: "A fake system for tests and dry runs. No real search, so it is fast and gives the same result every time.",
    steps: ["Read the repo's files with one suffix.", "Rank files by how many query words they contain.", "A script can fix the hits for a query, so runner tests know the right answer in advance."] },
  "cmeval.metrics.matching.hit_matches": { what: "Decides if one hit finds one gold class or function (Decisions 2 and 3).",
    steps: ["The hit is in another file, or it has no line numbers: no match.", "The hit lies inside the gold range: match (rule a).", "Else: match if <code>line_iou</code> of the two ranges is at least the threshold (rule b). The threshold is 0.5. The score also checks 0.3 and 0.7."],
    aside: "File level does not use this function. A hit finds a gold file when the paths are equal." },
  "cmeval.metrics.matching.line_iou": { what: "Line IoU of two line ranges: the lines in both ranges, divided by the lines in either range.",
    steps: ["Shared lines: from the later start to the earlier end, or 0 if the ranges do not overlap.", "Lines in either range: from the earlier start to the later end.", "Divide the first number by the second."],
    aside: "Example from scikit-learn-10908: a hit on lines 992 to 999 and the gold function on 994 to 999 share 6 lines, and 8 lines are in either. IoU = 6 / 8 = 0.75." },

  "cmeval.run.run": { what: "The runner. It runs every system in a config on every task and saves the raw hits and timings. A stopped run continues where it stopped.",
    steps: ["Load the tasks of the split and the systems. <code>order_tasks</code> groups the tasks by repo in commit-date order.", "Take the lock on the run folder (<code>FileLock</code>). Another process holds it: stop with an error.", "The run folder already has a <code>meta.json</code>: the inputs, the cmeval commit, and each system's index key and codemem commit must be the same. Else stop: \"use a new run id\".", "Add this start to the <code>sessions</code> list in <code>meta.json</code>.", "Cut an unfinished last line from each run file (<code>drop_unfinished_line</code>). Skip each task and system pair that is already done.", "For each repo: discard an old worktree and make a new one. For each task: move to its base commit, check that HEAD is that commit, build or update each index group, then search with each system and write one line.", "At the end, write status \"done\" (or \"failed\" with the error) in <code>meta.json</code>."],
    aside: "Tested with <code>kill -9</code> and SIGSTOP on <code>requests</code>: the resumed run gave identical hits and texts." },
  "cmeval.files.FileLock": { what: "An exclusive lock on a file, so two processes never work on one run at the same time.",
    steps: ["<code>acquire()</code>: open the file and ask the OS for an exclusive lock without waiting (<code>flock</code> on macOS and Linux, <code>msvcrt.locking</code> on Windows).", "Another process holds it: return False.", "<code>release()</code>: unlock and close the file."],
    aside: "The OS releases the lock when the process ends, also after <code>kill -9</code> or a crash. So a stopped run can always be resumed, and no stale lock file blocks it." },
  "cmeval.files.drop_unfinished_line": { what: "Cuts a last line that has no newline at the end. Such a line comes from a write that stopped, for example at a power loss.",
    steps: ["The file is missing or empty: do nothing.", "Read only the last byte. It is a newline: do nothing (the normal case).", "Else cut the file after the last newline and return True."],
    aside: "<code>append_jsonl</code> writes each line and its newline in one write. So a line without a newline was never finished, and the runner does that task again." },
  "cmeval.repos.discard_live": { what: "Removes the movable worktree of a run, in any state.",
    steps: ["The worktree folder does not exist: do nothing.", "Remove it with <code>git worktree remove</code>.", "That fails: delete the folder and run <code>git worktree prune</code>."],
    aside: "A process stopped during a checkout can leave local changes or a stale <code>index.lock</code>. Then <code>move_to</code> refuses the worktree. The runner always starts each repo with a new one." },
  "cmeval.score.run_tasks": { what: "Gives a run's tasks by ID, from the tasks file that the run used.",
    steps: ["Use <code>--tasks FILE</code> if given, else the path in <code>meta.json</code>.", "The file is missing: error (for a run from another machine, give <code>--tasks</code>).", "Its sha256 is not the run's: error. The labels would not match the hits.", "Load the tasks and key them by ID."] },

  "cmeval.compare.compare": { what: "The update vs. rebuild check (Decision 5). It compares two scored runs of the same tasks: one that updated the index from commit to commit, and one that built it new for each task.",
    steps: ["Both runs must be scored, with the same tasks file (sha256 checked), the same systems, and the same number of hits per search.", "Warn if the pair is not one update run and one rebuild run, if they used different codemem code (<code>code</code>), or if a run had uncommitted changes.", "For each system, use only the tasks that both runs searched and scored. Each task must have the same commit in both.", "Top 10: compare the sets of hit locations (path and lines), not the texts. Count the tasks with the same set.", "For a task with another set, list each hit that is in one top 10 only, with its rank and score in both runs and a hint: \"stale\", \"near tie\", or \"check\".", "Metrics: compare each mean. The limit is 0.01, and 1% (relative) for token counts.", "A system passes if at least 95% of its tasks have the same top 10 and no mean is over the limit.", "Write <code>compare-&lt;run B&gt;.md</code> in the folder of run A."],
    aside: "First check (seaborn, requests, pytest; 12 tasks): every top 10 was the same. One metric was over the limit: two hits with exactly equal scores swapped ranks 15 and 16, because ties were ordered by chunk id. Andrew passed it by hand, and codemem now orders ties by location (<code>61317d0</code>). It was run again at the reported codemem code (<code>93f7db1</code>) and passed with no hand judgement. All 6 systems had the same top 10 on 12 of 12 tasks. Every accuracy mean was the same, and the token means differed by less than 0.4%." },
  "cmeval.compare.in_code": { what: "Checks that a hit points at real code at the task's commit. The check finds a \"stale\" hit, which is a real update bug.",
    steps: ["Read the hit's file at the commit with <code>repos.read_file</code>. No file: False.", "The hit has an end line past the end of the file: False.", "Else True."] },
  "cmeval.adapters.grep_fn.GrepFnRetriever": { what: "grep-fn: the grep baseline plus the step an agent takes next. It returns the function around each matching line, so grep can be graded at function level. Four options make it closer to how an agent greps; all four together are grep-fn-plus.",
    steps: ["Take the keywords from the issue.", "With <code>clean_keywords</code>, drop keywords that cannot name code: web addresses, paths, file names, and commit hashes.", "Rank files. By default, a file scores its number of keyword matches.", "With <code>weighting = \"idf\"</code>, each keyword gets a weight: log(N / (1 + files that have it)) + 1. A rare word weighs more. A file scores the sum of the weights of its different keywords.", "With <code>types</code> (for example Python only): search only those file types, not docs, images, and data.", "Read the matching lines of the top 50 files.", "Each line goes to the innermost function around it. Lines outside every function are dropped.", "Score each function in the same way as a file. Keywords are counted on whole lines.", "With <code>tests_last</code>: functions in test files go after all others (the gold labeler's test rule).", "Return the functions in order, each with its line range and up to 10 of its matching lines."],
    aside: "The defaults are the naive ranking of the proposal (function MRR 0.068 on the early dev run, a 50-task SWE-bench sample). It lost for three reasons: 15 gold files never reached its 50-file budget, long functions that repeat one word won, and 47% of its top 10 were tests. grep-fn-plus fixes all three (0.316). It was tuned on the dev tasks, so it is a little flattered there." },
  "cmeval.adapters.grep.rg_files": { what: "The files that contain any of the keywords, or every searchable file if no keywords are given. grep-fn's IDF weights use it.",
    steps: ["No keywords: <code>rg --files</code> lists every file that ripgrep would search.", "Keywords: <code>rg --files-with-matches</code> lists the files that have at least one of them.", "Both respect .gitignore and the chosen file types."] },
  "cmeval.adapters.grep.preview_line": { what: "Cuts a long line for a hit's text, the way <code>rg --max-columns</code> shows it in an agent's grep output.",
    steps: ["Up to 300 bytes: the line as it is.", "Longer: the first 300 characters, then \"[... omitted end of long line]\"."],
    aside: "Only the hit text is cut. grep-fn counts keywords on the whole line, so a match after column 300 still counts. The test is in bytes and the cut is in characters. So for a line with non-ASCII text, the cut is not at the same place as rg's." },
  "cmeval.merge.merge": { what: "Adds the systems of one run to a copy of another run of the same tasks, so the report can compare them. A new system can run alone; the old systems need no new search.",
    steps: ["Both runs must be finished, with the same tasks file, split, hits per search, and index mode.", "Choose the systems of EXTRA that BASE does not have (or the ones named with <code>--system</code>). Each name must be new.", "EXTRA must have every task of BASE, at the same commit, so all systems are compared on the same tasks.", "Write a new run folder: the run files of BASE, plus the chosen systems' files and index rows.", "<code>meta.json</code> records both parts (code, machine, sessions) in <code>merged_from</code>. BASE and EXTRA do not change.", "Any error: delete the new folder, so no half-merged run is left. Score the new run next."],
    aside: "Example: run <code>2026-10-23-dev50-final</code>, an early dev run on a SWE-bench sample, is a merged run. Its 3 grep systems ran again after the grep-fn fixes; its 3 codemem systems came from an earlier run, so their slow index builds did not run again." },
  "cmeval.cli.cmd_merge": { what: "Runs <code>cmeval merge BASE EXTRA --run-id NEW</code> and prints the systems of the new run.",
    steps: ["Run <code>merge(base, extra, run_id, systems)</code>.", "Print the new run folder and its systems.", "Print the next step: <code>cmeval score NEW</code>."] },
  "cmeval.compare.code": { what: "The code a run used: cmeval's commit, and codemem's commit if a codemem system ran, each with an \"uncommitted changes\" flag.",
    steps: ["Read cmeval's commit from <code>meta.json</code>.", "Read codemem's commit from the first codemem system's settings.", "Return both, with their \"dirty\" flags."] },
  "cmeval.cli.cmd_compare": { what: "Runs <code>cmeval compare RUN_A RUN_B</code> and prints one line for each system.",
    steps: ["Run <code>compare(run_a, run_b)</code>.", "Print PASS or FAIL, then for each system: tasks, same top 10, largest metric difference, largest token difference.", "Print the path of the report."] },

  "cmeval.metrics.stats.bootstrap_ci": { what: "A 95% interval for the mean, made by resampling (percentile bootstrap).",
    steps: ["Fewer than 2 values: no interval.", "Take 10,000 resamples. Each draws n values with replacement (<code>resample_indexes</code>).", "Compute the mean of each resample and sort the means.", "The interval is the 2.5% and 97.5% quantiles of those means (<code>quantile</code>)."],
    aside: "The seed is fixed and the values come in sorted task order, so the same inputs always give the same interval. A run with fewer than 20 tasks gets a note in the report: at that size, the intervals are too narrow." },
  "cmeval.metrics.stats.resample_indexes": { what: "The resamples: for each one, n positions drawn with replacement. Every metric with n tasks uses the same draws.",
    steps: ["Seed a random generator with the text <code>\"&lt;seed&gt;:&lt;n&gt;:&lt;resamples&gt;\"</code>.", "Draw n positions from 0 to n-1, with replacement, once for each resample.", "Keep each resample as a compact array, with 2 or 4 bytes for each index.", "Keep the result in a cache for the next metric of the same size."],
    aside: "Python hashes a text seed with sha512, so the draws do not change with <code>PYTHONHASHSEED</code>." },
  "cmeval.metrics.stats.quantile": { what: "The q quantile of sorted values, with linear interpolation between neighbors. It gives the same result as the numpy default.",
    steps: ["Position = q &times; (n - 1).", "Take the values at the floor of the position and at the next position.", "Interpolate between them by the fraction part of the position."] },
  "cmeval.metrics.stats.differences": { what: "The difference x - y for each pair, rounded to 9 digits.",
    steps: ["Both lists must have the same length.", "Subtract each pair and round."],
    aside: "Scores have 6 digits. Without rounding, float noise looks like a real difference: 0.5 - 0.166667 is not exactly 0.333333." },
  "cmeval.metrics.stats.paired_bootstrap_ci": { what: "A 95% interval for the mean difference between two systems on the same tasks.",
    steps: ["Compute the difference for each task (<code>differences</code>).", "Give the differences to <code>bootstrap_ci</code>."],
    aside: "Each pair is one task, so to resample the differences is the same as to resample the tasks." },
  "cmeval.metrics.stats.wilcoxon": { what: "The two-sided Wilcoxon signed-rank test of paired differences. It gives the same p as <code>scipy.stats.wilcoxon</code> with its defaults.",
    steps: ["Drop the zero differences. No pairs, or all zero: no test.", "Rank the sizes of the differences. Equal sizes share their average rank.", "Statistic: the smaller of the positive rank sum and the negative rank sum.", "Small samples (up to 50 pairs with no ties and no zeros, or up to 13 pairs): exact p. Count the rank sums of all 2<sup>m</sup> sign patterns.", "Else: normal approximation, with a correction for ties."],
    aside: "Only the standard library is used, so the base install needs no scipy. Checked equal to scipy 1.17.1 on about 2,970 random cases." },
  "cmeval.metrics.stats.holm": { what: "The Holm correction: adjusted p-values for a family of tests that is fixed in advance.",
    steps: ["A missing p counts as 1, so the family size does not change.", "Sort the p-values from small to large.", "Multiply the p at step i (from 0) by (family size - i). Cap at 1.", "In that order, each adjusted p is at least the one before it.", "Return the adjusted p-values in the input order."],
    aside: "The family is 6 tests: the 3 codemem systems against the baseline (grep-fn-plus), on function MRR and function tokens to the first right answer. The list of systems is fixed in the design, so adding a system to a run never makes the family bigger." },

  "cmeval.report.report": { what: "Writes <code>report.md</code> for a scored run. It reads only the scored run files and the tasks file. No search and no network.",
    steps: ["Load <code>meta.json</code>, <code>score-meta.json</code>, <code>scores.jsonl</code>, and <code>summary.csv</code>. The run must be scored, and on the split that was asked for (the test split only when asked, Decision 1).", "Load the run's tasks with <code>run_tasks</code>.", "Main tables at file, function, and class level: each mean with a 95% bootstrap interval.", "Compare each system with the baseline (default grep-fn-plus, the stronger grep) on the same tasks: mean difference, paired interval, Wilcoxon p.", "The primary tests are fixed in the design: the 3 codemem systems (<code>PRIMARY_SYSTEMS</code>, or <code>--primary</code>) on function MRR and function tokens to the first right answer. These 6 p-values get one Holm correction. All other comparisons are exploratory, with a raw p.", "Then: group tables, the IoU check (0.3, 0.5, 0.7), latency and size, task counts, and warnings."],
    aside: "The primary metrics were fixed in the design, before any results. The same inputs always give the same report: sorted tasks, a fixed seed, and no time stamp. Look closer on REPORT, Write report, steps through a report with example numbers." },
  "cmeval.report.Scores": { what: "The per-task values from <code>scores.jsonl</code>, ready for tables and tests.",
    steps: ["Key each value by system, level, IoU, and metric, then by task.", "Keep the excluded tasks and their reasons apart.", "From each \"found\" value, add a \"not found share\" value (1 - found).", "<code>get</code> gives the values of one metric. File level has no IoU.", "<code>vector</code> gives them in sorted task order, without missing values."] },
  "cmeval.cli.cmd_report": { what: "Runs <code>cmeval report RUN</code> and prints the primary results.",
    steps: ["Run <code>report(run, baseline, split, cutoff)</code>.", "Print each warning.", "Print the path of the report and the task count.", "Print each primary test: system, metric, tasks, difference, Holm p."] },

  "cmeval.github.GitHub": { what: "All GitHub access of the collector. It calls the <code>gh</code> command, keeps each answer on disk, and tries short failures again.",
    steps: ["<code>graphql(query)</code> and <code>rest(path)</code> name each request by <code>cache_key</code>.", "An answer for that key is on disk (and <code>refresh</code> is off): return it with no network call.", "Else make a live call. Live calls are at least 0.25 s apart, because GitHub limits bursts.", "A short failure (HTTP 502, 503, 504, a time-out, a secondary rate limit): wait 15, 60, then 120 s and try again, up to 4 tries. Other errors stop at once.", "Save the answer on disk, but never an answer with errors.", "<code>graphql</code>: a live answer with fewer than 200 rate-limit points left stops the run. A cached answer does not, because its count is from the past.", "<code>allow_missing=True</code> accepts NOT_FOUND parts, for example a deleted issue in a batch of 50."],
    aside: "<code>gh</code> holds the login, so no token is in the code or in a file. The collector asks for fixed date windows, so a cached answer stays correct, and a second run of the same config needs no network." },
  "cmeval.github.cache_key": { what: "The file name of a cached answer: the sha256 of the request.",
    steps: ["Write the kind (graphql or rest), the request, and its variables as JSON with sorted keys and no spaces.", "Return the sha256 of that text."],
    aside: "The same request always gives the same key, so the cache finds it on the next run." },
  "cmeval.github.gh_runner": { what: "Runs <code>gh</code> once and returns what it printed.",
    steps: ["Run <code>gh</code> with the arguments. <code>gh</code> is not installed: <code>GitHubError</code>.", "Exit code 0: return the output.", "Else: if the output is a GraphQL answer with a <code>data</code> part, return it. The caller decides about its errors.", "Else: <code>GitHubError</code> with gh's message."],
    aside: "gh exits with 1 when one part of a batched answer is missing, but the other parts are still good." },

  "cmeval.collect.search.date_windows": { what: "Cuts a date range into windows of 7 days. Both ends are included.",
    steps: ["The end is before the start: no windows.", "From the start, take 7 days at a time.", "The last window ends on the last day, so it can be shorter."] },
  "cmeval.collect.search.search_merged_prs": { what: "Lists every PR merged into one branch in a date range, through GitHub's search.",
    steps: ["Cut the range into 7-day windows (<code>date_windows</code>).", "For each window, search <code>is:pr is:merged base:&lt;branch&gt; merged:&lt;start&gt;..&lt;end&gt;</code>, oldest first, in pages of 50 PRs.", "The search gives at most 1,000 results for one query. A window with more is cut in half, and each half is searched again, until each part fits.", "One day with more than 1,000 merged PRs: <code>GitHubError</code>, because no search can list them all.", "Each PR comes with its title, body, dates, author, commits and their messages, and GitHub's list of the issues it closes."],
    aside: "Pages of 50, not the maximum of 100: pages with long PR bodies and commit messages made GitHub time out. Example: the fresh-v1 config gave 21,822 merged PRs from 7 repos." },
  "cmeval.collect.search.is_bot": { what: "True if a PR or comment author is a bot.",
    steps: ["No author (a deleted account): not a bot.", "A GitHub App, or a login that ends in <code>[bot]</code>: a bot.", "A known bot account (dependabot, renovate, pre-commit-ci, and others), or a login in the config's <code>extra_bots</code>: a bot."] },

  "cmeval.collect.repo_stats.load_candidates": { what: "Reads a TOML file of candidate repos.",
    steps: ["Parse the TOML. It needs one or more <code>[[repo]]</code> tables.", "Each name must look like <code>owner/name</code>. A note is optional.", "A repo listed twice: <code>RepoStatsError</code>."] },
  "cmeval.collect.repo_stats.api_stats": { what: "A repo's size and languages, from the GitHub API.",
    steps: ["Read the repo: default branch, packed size, and if it is archived.", "Read the bytes for each language, largest first. GitHub leaves out vendored and generated files.", "Python share: Python bytes divided by all code bytes."] },
  "cmeval.collect.repo_stats.pr_funnel": { what: "A quick count of the possible tasks in a repo: the PRs left after each of 6 cheap filters.",
    steps: ["Merged into the default branch in the date range.", "The author is not a bot.", "GitHub's list says the PR closes exactly one issue, in the same repo.", "The issue was opened before the merge.", "At most 10 changed files of all kinds.", "The issue body has 100 or more characters, hidden comments removed."],
    aside: "The last count is an upper estimate. It is only for choosing repos; <code>cmeval collect</code> uses stricter rules and the checks that need git. Example: home-assistant had 1,226 possible tasks here and gave 756 tasks." },
  "cmeval.collect.repo_stats.code_stats": { what: "Counts what codemem would index in a repo today: Python files, lines, and chunks.",
    steps: ["Load codemem's own file walker, chunker, and settings. codemem is not installed: <code>RepoStatsError</code>.", "Clone only the newest commit of the branch (<code>shallow_clone</code>).", "Walk the Python files as codemem does. Skip files over codemem's size limit, and count them.", "For each file: count its lines, and chunk it. Count the chunks by kind (function, method, file header).", "Estimate the build time: chunks divided by 31 per second.", "Always delete the clone at the end."],
    aside: "The build time grows with the chunk count, so this number shows which repos are slow to index. The count matched codemem's real index of psf/requests (70 files, 500 chunks)." },
  "cmeval.collect.repo_stats.collect_stats": { what: "The numbers for each candidate repo: API numbers, the PR funnel, and (if asked) the code counts.",
    steps: ["For each repo: <code>api_stats</code>.", "<code>search_merged_prs</code> on its default branch, then <code>pr_funnel</code>.", "Code counts only with <code>--functions</code>, and only if Python is at least 30% of the code. Else record why they were skipped.", "Return one <code>RepoStats</code> for each repo."] },
  "cmeval.collect.repo_stats.render_markdown": { what: "Writes the repo numbers as three markdown tables.",
    steps: ["Size and languages: branch, packed size, code size, Python share, top 3 languages.", "The PR funnel: the 6 steps, then one row of counts for each repo.", "The code that codemem indexes: commit, files, lines, functions, methods, chunks, and build hours. A skipped repo shows the reason."] },
  "cmeval.cli.cmd_repo_stats": { what: "Runs <code>cmeval repo-stats</code>: the numbers to choose repos for fresh tasks.",
    steps: ["Take the repos from <code>--repo</code> and the <code>--candidates</code> file.", "Date range: <code>--since</code> (default 2026-07-01, the cutoff) to <code>--until</code> (default yesterday, so every day is complete and a cached answer stays right).", "Run <code>collect_stats</code>.", "Write <code>stats.md</code> and <code>stats.json</code> to <code>--out</code>, or <code>eval/results/&lt;today&gt;-repo-stats</code>.", "Print the tables, the API calls, and the cache hits."],
    aside: "Example: <code>results/2026-10-23-repo-stats</code> has the numbers for 16 candidates. Andrew chose 7 Python repos from them." },

  "cmeval.collect.links.issues_pattern": { what: "SWE-bench's link pattern: a word, white space, then <code>#</code> or the repo's issue address, then a number.",
    steps: ["Two markers: <code>#</code>, and <code>https://github.com/&lt;repo&gt;/issues/</code>.", "The pattern catches the word before the marker and the number after it."],
    aside: "A direct port of SWE-bench's rule. Example: airflow's PR template writes <code>closes: #N</code>. The colon is not white space, so this pattern finds only 61 of airflow's 315 candidate links." },
  "cmeval.collect.links.pr_text": { what: "The text that SWE-bench reads to find links: the PR title, the PR body, and every commit message, without HTML comments.",
    steps: ["Join the title, the body, and the commit messages with new lines.", "Remove hidden HTML comments (<code>&lt;!-- ... --&gt;</code>)."] },
  "cmeval.collect.links.regex_links": { what: "The issues that SWE-bench's method finds in a PR.",
    steps: ["Find each match of <code>issues_pattern</code> in <code>pr_text</code>.", "Keep the number if the word before it is a closing word: close, closes, closed, fix, fixes, fixed, resolve, resolves, resolved (any case)."] },
  "cmeval.collect.links.list_links": { what: "The issues in GitHub's own closing list for a PR, in the same repo.",
    steps: ["Read <code>closingIssuesReferences</code>.", "Keep the issues of the same repo."],
    aside: "GitHub fills this list from closing words in the PR description and from links set by hand on the PR page. GitHub uses this list to close issues." },
  "cmeval.collect.links.find_links": { what: "Runs both link methods on a PR, and records which method found each issue.",
    steps: ["Get the issues from <code>list_links</code> and from <code>regex_links</code>.", "For each issue in either set: \"both\", \"list\" (GitHub's list only), or \"regex\" (SWE-bench's rule only)."],
    aside: "Example: of the 3,002 fresh-v1 candidates, 2,646 were found by both methods, 334 by the list only, and 22 by the regex only. So SWE-bench's own rule finds 89% of the links, and a strict SWE-bench subset is one filter on the task file." },

  "cmeval.collect.issues.fetch_issues": { what: "Fetches many issues with their edit history, renames, and comments, 50 in one GraphQL query.",
    steps: ["Sort the issue numbers, so the same set always gives the same batches and the cache answers a second run.", "For each batch of 50: one query with one part for each number.", "A number that is a PR gives its type only. A number with no issue gives None."] },
  "cmeval.collect.issues.body_at": { what: "The issue body as it was at one moment: the moment the fix PR was opened (Decision 8).",
    steps: ["Sort the stored body versions from old to new.", "No version is newer than that moment: the current body is the body at that moment.", "Else take the newest version from before that moment. There is none: take the oldest version, the original.", "Flag that the body was edited after that moment.", "Flag a version whose text GitHub did not store. That candidate is dropped."],
    aside: "A later edit can describe the fix, so the query uses the earlier text. GitHub did not store the text of edits from before about 2018. That is why the old versions are read only when the body changed after the fix PR was opened. Example: in fresh-v1, 251 bodies were edited after the fix." },
  "cmeval.collect.issues.title_at": { what: "The issue title as it was when the fix PR was opened.",
    steps: ["Sort the \"renamed\" events from old to new.", "A rename came after that moment: the title is the old title of the first such rename, and it is flagged.", "Else the current title."],
    aside: "Decision 8 names only the body. The title is handled the same way because a rename can also describe the fix. Example: 26 titles in fresh-v1." },
  "cmeval.collect.issues.hints_before": { what: "The comments written before the fix PR was opened. They are stored in the task but not used in the main eval.",
    steps: ["Keep the comments from before that moment whose author is not a bot.", "Remove hidden HTML comments, and drop empty ones.", "Join them with blank lines. None if no comment is left."] },
  "cmeval.collect.issues.build_query": { what: "The search query of a task: the issue title and body.",
    steps: ["Remove hidden HTML comments from the body.", "Join as <code>&lt;title&gt;</code>, a blank line, then <code>&lt;body&gt;</code>."],
    aside: "Code blocks, stack traces, and visible template text stay. An agent would see them too." },
  "cmeval.collect.issues.leak": { what: "Finds a query that gives away the fix. It returns the reason, or None.",
    steps: ["The query names the fix PR: <code>#&lt;number&gt;</code> or <code>/pull/&lt;number&gt;</code>. <code>&amp;#</code> does not count, because that is an HTML character code.", "Each word of 7 to 40 hex characters that starts a commit ID of the fix PR or its merge commit."],
    aside: "A candidate with a leak is dropped and its reason goes to the funnel." },

  "cmeval.collect.candidates.load_settings": { what: "Reads a collection config, for example <code>configs/fresh-v1.toml</code>.",
    steps: ["Parse the TOML. Read the repos with <code>load_candidates</code>.", "The <code>[collect]</code> table needs <code>since</code> and <code>until</code>. Unknown keys are an error.", "Optional: <code>min_body_chars</code> (100), <code>extra_bots</code>, <code>max_code_files</code> (5), <code>max_code_lines</code> (200). Each must have the right type.", "The name of the settings is the file name without <code>.toml</code>."] },
  "cmeval.collect.candidates.Funnel": { what: "The yield funnel of one repo: how many PRs are left after each of the 13 steps, and why each PR was dropped.",
    steps: ["<code>counts</code>: one count for each step, in order. The 5 git steps stay empty after a dry run.", "<code>drop(pr, step, reason)</code> records one dropped PR.", "<code>drop_reasons()</code> counts the reasons, without their details in brackets.", "<code>link_methods</code>: how the candidates' links were found (list, regex, both)."],
    aside: "Like SWE-bench's 93,139 PRs to 2,294 tasks, this table goes into the report. Example: fresh-v1 goes from 21,822 PRs to 3,002 candidates to 2,084 tasks." },
  "cmeval.collect.candidates.collect_candidates": { what: "The GitHub steps of the collector for one repo: from merged PRs to candidates, each with one issue and a query.",
    steps: ["List the PRs merged into the default branch in the date range (<code>search_merged_prs</code>).", "The fix PR was opened on or after the start date. Its code was not public before the model's training data ends.", "The author is not a bot.", "<code>find_links</code> finds exactly one issue in the same repo. None or several: drop.", "Fetch the linked issues (<code>fetch_issues</code>). The link must be an issue that exists, not a PR.", "The issue was opened before the fix PR, so it was not written after the fix.", "The body at that moment (<code>body_at</code>) has at least the minimum length.", "Build the query from the title and body at that moment. <code>leak</code> finds none.", "Record the PR, its commits, the issue, the query, the hints, the link method, and the \"edited after the fix\" tags."],
    aside: "Each dropped PR goes to the funnel with its step and reason. Example: fresh-v1 gives 3,002 candidates from 21,822 merged PRs." },
  "cmeval.collect.candidates.write_candidates": { what: "Writes one repo's candidates and its funnel.",
    steps: ["<code>candidates.jsonl</code>: one JSON line for each candidate.", "<code>funnel.json</code>: the counts, the drops, and the drop reasons."],
    aside: "The files go to <code>CMEVAL_HOME/collect/&lt;config&gt;/&lt;owner&gt;__&lt;name&gt;/</code>, outside the repo." },
  "cmeval.collect.candidates.render_funnel": { what: "Writes the funnel as markdown tables, one row for each repo and a total row.",
    steps: ["GitHub steps: the 8 counts and the three link methods.", "Git steps: the 5 counts, only if the git steps ran (not a dry run)."] },

  "cmeval.collect.tasks_build.merge_base": { what: "Finds the base commit of a merged PR, the code just before the fix, from the way the PR was merged (Decision 7).",
    steps: ["No merge commit, or git cannot find it: drop.", "The commit has two parents: a merge commit. Base = its first parent.", "The PR has N commits (N &gt; 1), and the last N commits on the branch have the same subjects as the PR's commits: a rebase merge. Base = N commits back.", "Else: a squash merge. Base = its parent."],
    aside: "A rebase of one commit looks the same as a squash, and both give the same base. Example: all 2,084 fresh-v1 tasks are squash merges, so the merge-commit and rebase rules are checked only by tests with real git histories." },
  "cmeval.collect.tasks_build.patch_paths": { what: "The paths that a patch touches, the way GitHub lists them.",
    steps: ["Parse the patch.", "For each file: its new path, or its old path if it was deleted."] },
  "cmeval.collect.tasks_build.fetch_pr_files": { what: "The file list of many PRs from GitHub, 50 PRs in one query.",
    steps: ["Sort the PR numbers and fetch them in batches of 50.", "Each PR gives its file paths.", "A PR with more than 100 files gives None. Such a PR is far over the code-file limit."] },
  "cmeval.collect.tasks_build.candidate_to_task": { what: "The git steps for one candidate: base, patch, checks, labels, and the task. A candidate that fails a step raises <code>Skip</code> with the step and the reason.",
    steps: ["Base commit and merge type (<code>merge_base</code>).", "The PR has more than 100 files: drop before the diff, because such diffs are slow.", "Make our own patch with <code>git diff -M</code> from the base to the merge commit. Its paths must equal GitHub's file list for the PR.", "Split the patch into code, test, and other. The code part must apply at the base (<code>apply_check</code>).", "Size: 1 to 5 code files, and at most 200 added and removed code lines.", "Label the code part at the base commit. At least one gold file must exist at the base, not only new files.", "Build the task: ID <code>&lt;owner&gt;__&lt;name&gt;-&lt;PR&gt;</code>, split from the hash of the ID, the query, the hints, the patches, the gold labels, and the tags.", "<code>validate</code> must find no problem.", "A git error in any step drops only this candidate, with that step."],
    aside: "We make the patch ourselves, so the patch and the base snapshot always match. Tags: <code>gold_languages</code> and <code>gold_all_python</code> (the main comparison uses only all-Python tasks), the size of the largest gold file (codemem skips files over 1 MB), <code>repo_py_files</code> (the repo size at the base, for the small, medium, and large groups), and <code>link_method</code>." },
  "cmeval.collect.tasks_build.count_py_files": { what: "The number of Python files in a repo at one commit: the repo size tag.",
    steps: ["List every file in the commit's tree (<code>tracked_files</code>).", "Count the paths that end in <code>.py</code>."] },
  "cmeval.collect.tasks_build.gold_file_stats": { what: "The bytes and lines of the largest gold file at the base commit.",
    steps: ["Read each gold file at the base.", "Return the largest (bytes, lines) pair."] },
  "cmeval.collect.tasks_build.build_tasks": { what: "The git steps of the collector for one repo: from candidates to tasks. It fills the 5 git steps of the funnel.",
    steps: ["No candidates: all git counts are 0.", "Clone the repo once (<code>ensure_clone</code>), and get every PR's file list (<code>fetch_pr_files</code>).", "For each candidate: <code>candidate_to_task</code>. A <code>Skip</code> goes to the funnel with its step and reason.", "Each git step counts the candidates that passed it.", "Tasks that share a base commit share one repo size count."],
    aside: "Example: the 3,002 fresh-v1 candidates gave 2,084 tasks in 11 minutes. The largest drop: 660 fixes changed no code file." },
  "cmeval.collect.tasks_build.write_task_set": { what: "Writes the task file for all repos and its <code>.meta.json</code> file next to it.",
    steps: ["Sort the tasks by repo, then by merge time, then by ID.", "Save them with <code>save_tasks</code> (all are checked first; a crash cannot leave half a file).", "Count the label stats, the tasks in each split, the all-Python share, and the merge types.", "Write the meta file: config, dates, settings, cmeval version and commit, labeler version, the 13 funnel steps, and each repo's counts and drop reasons."],
    aside: "Example: <code>tasks/fresh-v1.jsonl</code> has 2,084 tasks (399 dev, 1,685 test) from 7 repos; 91% are all-Python." },
  "cmeval.cli.cmd_collect": { what: "Runs <code>cmeval collect CONFIG</code>: GitHub steps, then git steps, then the task file.",
    steps: ["Read the config (<code>load_settings</code>). <code>--repo</code> keeps only the named repos of the config.", "For each repo: <code>collect_candidates</code> (GitHub steps).", "Not a dry run: <code>build_tasks</code> (git steps), then <code>write_candidates</code>.", "Print the funnel tables (<code>render_funnel</code>).", "Not a dry run: write the task file with <code>write_task_set</code>, to <code>--out</code> or <code>eval/tasks/&lt;config name&gt;.jsonl</code>.", "Print the API calls, the cache hits, and the retries."],
    aside: "<code>--dry-run</code> runs only the GitHub steps and writes nothing, so it counts the candidates with no clone." },

  "cmeval.repos.shallow_clone": { what: "Checks out only the newest commit of one branch, with no history. Returns its sha.",
    steps: ["<code>git clone --depth 1 --single-branch</code> with <code>core.autocrlf=false</code>.", "Return the sha of HEAD."],
    aside: "Much smaller than a full clone. Only <code>repo-stats</code> uses it, for numbers about today's code. The collector and the runner need the full history." },
  "cmeval.repos.parents": { what: "The parent commits of a commit, first parent first.",
    steps: ["<code>ensure_commit</code>.", "<code>git rev-list --parents -n 1</code> and drop the commit itself."],
    aside: "One parent: a squash or rebase merge. Two parents: a merge commit." },
  "cmeval.repos.ancestor": { what: "The full sha of the commit n first-parent steps back (<code>sha~n</code>).",
    steps: ["<code>git rev-parse --verify sha~n</code>."] },
  "cmeval.repos.subjects": { what: "The first message lines of a commit and its n - 1 first-parent ancestors, oldest first.",
    steps: ["<code>git log --first-parent -n</code> with the subject only.", "Reverse the list, so the oldest is first."],
    aside: "<code>merge_base</code> compares them with the PR's commits to find a rebase merge." },
  "cmeval.repos.diff": { what: "The unified diff from one commit to another, the way git prints it. It needs no worktree.",
    steps: ["<code>ensure_commit</code> for both commits.", "<code>git diff -M</code> (renames found), with no color and no external diff tool.", "Read the bytes as UTF-8."] },
  "cmeval.repos.tracked_files": { what: "Every file path in the tree of a commit, with no worktree.",
    steps: ["<code>ensure_commit</code>.", "<code>git ls-tree -r --name-only</code>."] },
  "cmeval.repos.apply_check": { what: "Checks that a patch applies to the code at a commit. None if it applies, else git's message.",
    steps: ["<code>ensure_commit</code>.", "In a temporary folder, load the commit's tree into a temporary index file (<code>git read-tree</code>). A failure: <code>RepoError</code>.", "<code>git apply --check --cached</code> the patch against that index.", "Delete the temporary folder."],
    aside: "The temporary index works in the bare clone and changes nothing in it." },

};
